// ============================================================================
// HDMI_CEC_apb: APB4 register wrapper around HDMI_CEC_top (generated by
// scripts/apb/gen_apb.py from scripts/apb/specs/HDMI_CEC.json; do not edit)
// ----------------------------------------------------------------------------
//  - APB4 slave, zero wait states (PREADY = PSEL & PENABLE), 32-bit data,
//    12-bit byte address; PSLVERR on an unmapped or misaligned access.
//  - PSTRB byte lanes apply to every writable register.
//  - The core runs on PCLK/PRESETN; protocol pins pass through unchanged.
//  - Register map: docs/ip/HDMI_CEC.md
// ============================================================================
module HDMI_CEC_apb #(
  parameter logic [3:0] AXI_ID = 4'd7
) (
  input  logic        PCLK,
  input  logic        PRESETN,
  input  logic        PSEL,
  input  logic        PENABLE,
  input  logic        PWRITE,
  input  logic [11:0] PADDR,
  input  logic [31:0] PWDATA,
  input  logic [3:0]  PSTRB,
  output logic [31:0] PRDATA,
  output logic        PREADY,
  output logic        PSLVERR,
  output logic        irq,
  input logic cec_in,
  output logic cec_oe_low,
  output logic [3:0] m_awid,
  output logic [31:0] m_awaddr,
  output logic [7:0] m_awlen,
  output logic [2:0] m_awsize,
  output logic [1:0] m_awburst,
  output logic [2:0] m_awprot,
  output logic m_awvalid,
  input logic m_awready,
  output logic [31:0] m_wdata,
  output logic [3:0] m_wstrb,
  output logic m_wlast,
  output logic m_wvalid,
  input logic m_wready,
  input logic [3:0] m_bid,
  input logic [1:0] m_bresp,
  input logic m_bvalid,
  output logic m_bready,
  output logic [3:0] m_arid,
  output logic [31:0] m_araddr,
  output logic [7:0] m_arlen,
  output logic [2:0] m_arsize,
  output logic [1:0] m_arburst,
  output logic [2:0] m_arprot,
  output logic m_arvalid,
  input logic m_arready,
  input logic [3:0] m_rid,
  input logic [31:0] m_rdata,
  input logic [1:0] m_rresp,
  input logic m_rlast,
  input logic m_rvalid,
  output logic m_rready
);
  localparam logic [31:0] ID_VALUE = 32'h7C060100;

  // ---------------- APB decode ----------------
  wire        acc     = PSEL & PENABLE;
  wire        wr      = acc & PWRITE;
  wire        rd      = acc & ~PWRITE;
  wire [31:0] wmask   = {{8{PSTRB[3]}}, {8{PSTRB[2]}}, {8{PSTRB[1]}}, {8{PSTRB[0]}}};
  logic [14:0] hit;
  always_comb begin
    hit = '0;
    if (PADDR[1:0] == 2'b00 && PADDR[11:2] < 10'd15) hit[PADDR[11:2]] = 1'b1;
  end
  assign PREADY  = acc;
  assign PSLVERR = acc & ~|hit;

  // ---------------- core ----------------
  logic          c_enable;
  logic [15:0]   c_tick_div;
  logic [3:0]    c_la;
  logic          c_promisc;
  logic [9:0]    c_sft;
  logic [31:0]   c_rx_base;
  logic [7:0]    c_rx_slots;
  logic [7:0]    c_rx_rd;
  logic [31:0]   c_tx_addr;
  logic          c_tx_start;
  logic [7:0]    c_rx_wr;
  logic [15:0]   c_rx_cnt;
  logic [15:0]   c_rx_err_cnt;
  logic [15:0]   c_rx_ovf_cnt;
  logic [3:0]    c_tx_status;
  logic          c_tx_busy;
  logic          c_rx;
  logic          c_rx_err;
  logic          c_tx_done;
  logic          c_err_irq;
  HDMI_CEC_top #(.AXI_ID(AXI_ID)) u_core (
    .clk(PCLK),
    .rst_n(PRESETN),
    .cec_in(cec_in),
    .cec_oe_low(cec_oe_low),
    .enable(c_enable),
    .tick_div(c_tick_div),
    .la(c_la),
    .promisc(c_promisc),
    .sft(c_sft),
    .rx_base(c_rx_base),
    .rx_slots(c_rx_slots),
    .rx_rd(c_rx_rd),
    .tx_addr(c_tx_addr),
    .tx_start(c_tx_start),
    .rx_wr(c_rx_wr),
    .rx_cnt(c_rx_cnt),
    .rx_err_cnt(c_rx_err_cnt),
    .rx_ovf_cnt(c_rx_ovf_cnt),
    .tx_status(c_tx_status),
    .tx_busy(c_tx_busy),
    .rx(c_rx),
    .rx_err(c_rx_err),
    .tx_done(c_tx_done),
    .err_irq(c_err_irq),
    .m_awid(m_awid),
    .m_awaddr(m_awaddr),
    .m_awlen(m_awlen),
    .m_awsize(m_awsize),
    .m_awburst(m_awburst),
    .m_awprot(m_awprot),
    .m_awvalid(m_awvalid),
    .m_awready(m_awready),
    .m_wdata(m_wdata),
    .m_wstrb(m_wstrb),
    .m_wlast(m_wlast),
    .m_wvalid(m_wvalid),
    .m_wready(m_wready),
    .m_bid(m_bid),
    .m_bresp(m_bresp),
    .m_bvalid(m_bvalid),
    .m_bready(m_bready),
    .m_arid(m_arid),
    .m_araddr(m_araddr),
    .m_arlen(m_arlen),
    .m_arsize(m_arsize),
    .m_arburst(m_arburst),
    .m_arprot(m_arprot),
    .m_arvalid(m_arvalid),
    .m_arready(m_arready),
    .m_rid(m_rid),
    .m_rdata(m_rdata),
    .m_rresp(m_rresp),
    .m_rlast(m_rlast),
    .m_rvalid(m_rvalid),
    .m_rready(m_rready)
  );

  // ---------------- registers ----------------
  logic [3:0] irq_status, irq_enable, irq_set;
  logic [31:0] scratch;
  logic [5:0] r_CTRL;   // 12'h014 CTRL
  logic [25:0] r_TIMING;   // 12'h018 TIMING
  logic [31:0] r_RX_BASE;   // 12'h01C RX_BASE
  logic [15:0] r_RX_RING;   // 12'h020 RX_RING
  logic [31:0] r_TX_ADDR;   // 12'h024 TX_ADDR
  logic [0:0] p_CMD;   // 12'h028 CMD (pulses)

  always_ff @(posedge PCLK or negedge PRESETN) begin
    if (!PRESETN) begin
      irq_status <= '0; irq_enable <= '0; scratch <= '0;
      r_CTRL <= 6'h0;
      r_TIMING <= 26'h0;
      r_RX_BASE <= 32'h0;
      r_RX_RING <= 16'h0;
      r_TX_ADDR <= 32'h0;
      p_CMD <= '0;
    end else begin
      irq_status <= (irq_status & ~((wr && hit[1]) ? PWDATA[3:0] & wmask[3:0] : '0)) | irq_set;
      if (wr && hit[2]) irq_enable <= (irq_enable & ~wmask[3:0]) | (PWDATA[3:0] & wmask[3:0]);
      if (wr && hit[4]) scratch <= (scratch & ~wmask) | (PWDATA & wmask);
      if (wr && hit[5]) r_CTRL <= (r_CTRL & ~wmask[5:0]) | (PWDATA[5:0] & wmask[5:0]);
      if (wr && hit[6]) r_TIMING <= (r_TIMING & ~wmask[25:0]) | (PWDATA[25:0] & wmask[25:0]);
      if (wr && hit[7]) r_RX_BASE <= (r_RX_BASE & ~wmask[31:0]) | (PWDATA[31:0] & wmask[31:0]);
      if (wr && hit[8]) r_RX_RING <= (r_RX_RING & ~wmask[15:0]) | (PWDATA[15:0] & wmask[15:0]);
      if (wr && hit[9]) r_TX_ADDR <= (r_TX_ADDR & ~wmask[31:0]) | (PWDATA[31:0] & wmask[31:0]);
      p_CMD <= (wr && hit[10]) ? PWDATA[0:0] & wmask[0:0] : '0;
    end
  end

  // ---------------- core inputs ----------------
  assign c_enable = r_CTRL[0:0];
  assign c_la = r_CTRL[4:1];
  assign c_promisc = r_CTRL[5:5];
  assign c_tick_div = r_TIMING[15:0];
  assign c_sft = r_TIMING[25:16];
  assign c_rx_base = r_RX_BASE[31:0];
  assign c_rx_slots = r_RX_RING[7:0];
  assign c_rx_rd = r_RX_RING[15:8];
  assign c_tx_addr = r_TX_ADDR[31:0];
  assign c_tx_start = p_CMD;

  // ---------------- interrupts and flags ----------------
  always_comb begin
    irq_set = '0;
    irq_set[0] = c_rx;
    irq_set[1] = c_rx_err;
    irq_set[2] = c_tx_done;
    irq_set[3] = c_err_irq;
  end
  assign irq = |(irq_status & irq_enable);

  // ---------------- read mux ----------------
  logic [31:0] apb_rdata;
  always_comb begin
    apb_rdata = '0;
    case (PADDR[11:2])
      10'd0: apb_rdata = ID_VALUE;
      10'd1: apb_rdata = 32'(irq_status);
      10'd2: apb_rdata = 32'(irq_enable);
      10'd4: apb_rdata = scratch;
      10'd5: apb_rdata = 32'(r_CTRL);
      10'd6: apb_rdata = 32'(r_TIMING);
      10'd7: apb_rdata = 32'(r_RX_BASE);
      10'd8: apb_rdata = 32'(r_RX_RING);
      10'd9: apb_rdata = 32'(r_TX_ADDR);
      10'd11: apb_rdata = 32'({c_rx_wr});
      10'd12: apb_rdata = 32'({c_tx_busy, c_tx_status});
      10'd13: apb_rdata = 32'({c_rx_err_cnt, c_rx_cnt});
      10'd14: apb_rdata = 32'({c_rx_ovf_cnt});
      default: apb_rdata = '0;
    endcase
  end
  assign PRDATA = (rd && |hit) ? apb_rdata : '0;
endmodule
